sp_widget.client_script:
api.controller = function($scope, $timeout, $sce) {
    var c = this;
    var POLL_MS = 5000;
    var MAX_POLLS = 48;   // 4 minutes
    var polls = 0;
    var pollPromise = null;

    c.customer = { value: '', displayValue: '' };
    c.running = false;
    c.view = null;
    c.error = '';

    // ---- Customer selected ----
    $scope.$on('field.change', function(evt, parms) {
        if (parms.field !== c.customer) return;
        stopPolling();
        c.view = null;
        c.error = '';
        c.running = false;
        if (!c.customer.value) return;

        c.server.get({ action: 'load', customer: c.customer.value }).then(function(r) {
            var d = r.data;
            if (d.reusable) {
                setResult(d.result);
            } else if (d.inProgress) {
                c.running = true;
                polls = 0;
                poll(d.recordId);
            } else {
                c.start();
            }
        });
    });

    // ---- Start / re-assess ----
    c.start = function() {
        if (!c.customer.value) return;
        stopPolling();
        c.error = '';
        c.view = null;
        c.running = true;
        polls = 0;

        c.server.get({
            action: 'start',
            customer: c.customer.value,
            customerName: c.customer.displayValue
        }).then(function(r) {
            if (r.data.error || !r.data.recordId) {
                c.running = false;
                c.error = r.data.error || 'Could not start the assessment.';
                return;
            }
            poll(r.data.recordId);
        });
    };

    // ---- Polling ----
    function poll(recordId) {
        pollPromise = $timeout(function() {
            polls++;
            c.server.get({ action: 'poll', recordId: recordId }).then(function(r) {
                var res = r.data.result;
                if (res && res.status === 'completed') {
                    c.running = false;
                    setResult(res);
                } else if (res && res.status === 'failed') {
                    c.running = false;
                    c.error = 'The assessment failed. Please click Re-assess to try again.';
                } else if (polls >= MAX_POLLS) {
                    c.running = false;
                    c.error = 'The assessment is taking longer than expected. Select the customer again in a few minutes to see the result.';
                } else {
                    poll(recordId);
                }
            });
        }, POLL_MS);
    }

    function stopPolling() {
        if (pollPromise) $timeout.cancel(pollPromise);
        pollPromise = null;
    }

    $scope.$on('$destroy', stopPolling);

    // ---- Build the view once per result ----
    function setResult(res) {
        var risk = parseRisk(res.final_recommendation);
        var news = parseNews(res.recent_news);
        c.view = {
            updated: res.updated,
            company: res.company_name || res.customer,
            price: res.current_stock_price,
            overview: res.company_overview,
            financials: parseBullets(res.financial_highlights),
            developments: parseBullets(res.major_developments),
            news: news,
            alertCount: news.filter(function(n) { return n.alert; }).length,
            risk: risk,
            riskClass: (risk.split(' ')[0] || '').toLowerCase(),
            recoHtml: toHtml(res.final_recommendation)
        };
    }

    // "* Label: text" lines -> [{label, text}]
    function parseBullets(text) {
        return lines(text).map(function(l) {
            var idx = l.indexOf(':');
            if (idx > 0 && idx < 45) {
                return { label: l.substring(0, idx).trim(), text: l.substring(idx + 1).trim() };
            }
            return { label: '', text: l };
        });
    }

    // "* Headline (Publisher, Date) | url" lines -> [{title, meta, url, alert}]
    function parseNews(text) {
        return lines(text).map(function(l) {
            var url = '';
            var pipe = l.lastIndexOf('|');
            if (pipe > -1) {
                var tail = l.substring(pipe + 1).trim();
                if (/^https?:\/\//i.test(tail)) url = tail;
                l = l.substring(0, pipe).trim();
            }
            var alert = /^\[ALERT\]/i.test(l);
            l = l.replace(/^\[ALERT\]\s*/i, '');

            var meta = '';
            var m = l.match(/\(([^()]*)\)\s*$/);
            if (m) {
                meta = m[1];
                l = l.substring(0, m.index).trim();
            }
            return { title: l, meta: meta, url: url, alert: alert };
        });
    }

    function lines(text) {
        return (text || '').split(/\r?\n/)
            .map(function(l) { return l.trim(); })
            .filter(function(l) { return /^[\*\-•]/.test(l); })
            .map(function(l) { return l.replace(/^[\*\-•]\s*/, ''); })
            .filter(Boolean);
    }

    function parseRisk(txt) {
        var m = (txt || '').match(/Risk Category:\s*(Low|Moderate|High)\s*Risk/i);
        return m ? m[1].charAt(0).toUpperCase() + m[1].slice(1).toLowerCase() + ' Risk' : '';
    }

    function toHtml(text) {
        if (!text) return '';
        var html = text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/^(Risk Category:|Reason:|Strengths:|Concerns:|Recommendation:)/gm, '<strong>$1</strong>');
        return $sce.trustAsHtml(html);
    }
};

sp_widget.css:
.vra .vra-input { margin-bottom:16px; }
.vra .vra-input label { display:block; margin-bottom:4px; font-weight:600; }

.vra .vra-running { display:flex; gap:16px; align-items:center; padding:16px; background:#f4f8fb; border-radius:6px; margin-bottom:16px; }

.vra .vra-toolbar { display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; flex-wrap:wrap; gap:8px; }

.vra .vra-head { display:flex; gap:32px; flex-wrap:wrap; padding:12px 0 16px; border-bottom:1px solid #e5e5e5; margin-bottom:12px; }
.vra .vra-label { font-size:12px; color:#777; text-transform:uppercase; letter-spacing:.5px; }
.vra .vra-value { font-size:18px; font-weight:600; }

.vra .vra-badge { display:inline-block; padding:4px 12px; border-radius:12px; font-weight:600; color:#fff; background:#888; }
.vra .vra-badge.low { background:#2e7d32; }
.vra .vra-badge.moderate { background:#ef6c00; }
.vra .vra-badge.high { background:#c62828; }

.vra .vra-section { margin-top:18px; }
.vra h4 { font-weight:600; margin-bottom:8px; }
.vra h4 .fa { color:#1f6fb2; margin-right:4px; }

.vra .vra-text { line-height:1.6; white-space:pre-wrap; word-break:break-word; }
.vra .vra-block { background:#fafafa; padding:12px 14px; border-radius:4px; }

.vra .vra-list { padding-left:20px; margin:0; }
.vra .vra-list li { margin-bottom:6px; line-height:1.55; }

.vra .vra-news-list a { font-weight:600; color:#1f6fb2; }
.vra .vra-news-list .fa-external-link { font-size:11px; }
.vra .vra-meta { color:#777; font-size:12px; margin-left:4px; }
.vra .vra-news-alert { background:#fff5f5; border-left:3px solid #c62828; padding:4px 8px; border-radius:3px; list-style-position:inside; margin-left:-20px; }
.vra .vra-alert { display:inline-block; background:#c62828; color:#fff; font-size:11px; font-weight:700; padding:1px 6px; border-radius:3px; margin-right:6px; }
.vra .vra-alert-box { margin-bottom:8px; }

sp_widget.script:
(function() {
    var TABLE = 'x_birl3_clm_customer_performance';
    var REUSE_HOURS = 24;     // show an existing completed assessment if newer than this; 0 = always re-run
    var STALE_MINUTES = 10;   // a 'requested' record older than this is treated as stuck and restarted

    if (!input) return;

    // ---- Load existing assessment for the selected customer ----
    if (input.action === 'load' && input.customer) {
        var rec = new GlideRecordSecure(TABLE);
        rec.addQuery('customer_name', input.customer);
        rec.orderByDesc('sys_updated_on');
        rec.setLimit(1);
        rec.query();
        if (rec.next()) {
            var age = ageHours(rec);
            data.result = pack(rec);
            data.recordId = rec.getUniqueValue();
            data.reusable = rec.getValue('assessment_status') === 'completed' &&
                            REUSE_HOURS > 0 && age < REUSE_HOURS;
            data.inProgress = rec.getValue('assessment_status') === 'requested' &&
                              age * 60 < STALE_MINUTES;
        }
        return;
    }

    // ---- Start a new assessment ----
    if (input.action === 'start' && input.customer) {
        var gr = new GlideRecordSecure(TABLE);
        gr.addQuery('customer_name', input.customer);
        gr.orderByDesc('sys_updated_on');
        gr.setLimit(1);
        gr.query();
        var exists = gr.next();

        if (exists && gr.getValue('assessment_status') === 'requested' &&
            ageHours(gr) * 60 < STALE_MINUTES) {
            data.recordId = gr.getUniqueValue();
            return;
        }

        if (!exists) {
            gr.initialize();
            gr.setValue('customer_name', input.customer);
            gr.setValue('company_name', input.customerName || '');
        }
        gr.setValue('current_stock_price', '');
        gr.setValue('market_stock_insight', '');
        gr.setValue('financial_highlights', '');
        gr.setValue('major_developments', '');
        gr.setValue('key_news_highlights', '');
        gr.setValue('final_recommendation', '');
        gr.setValue('requested_by', gs.getUserID());
        gr.setValue('assessment_status', 'requested');

        data.recordId = exists ? gr.update() : gr.insert();
        if (!data.recordId) data.error = 'Could not start the assessment: ' + gr.getLastErrorMessage();
        return;
    }

    // ---- Poll a running assessment ----
    if (input.action === 'poll' && input.recordId) {
        var p = new GlideRecordSecure(TABLE);
        if (p.get(input.recordId)) data.result = pack(p);
        return;
    }

    // ---------- helpers ----------
    function pack(r) {
        return {
            status: r.getValue('assessment_status'),
            customer: r.getDisplayValue('customer_name'),
            company_name: r.getValue('company_name'),
            current_stock_price: r.getValue('current_stock_price'),
            company_overview: r.getValue('market_stock_insight'),
            financial_highlights: r.getValue('financial_highlights'),
            major_developments: r.getValue('major_developments'),
            recent_news: r.getValue('key_news_highlights'),
            final_recommendation: r.getValue('final_recommendation'),
            updated: r.getDisplayValue('sys_updated_on')
        };
    }

    function ageHours(r) {
        var updated = new GlideDateTime(r.getValue('sys_updated_on'));
        var now = new GlideDateTime();
        return (now.getNumericValue() - updated.getNumericValue()) / 3600000;
    }
})();
